// Agoda — palindromic substrings (LeetCode 647), then the longest one (LeetCode 5). Expand around centres.
public static class Palindromes {
    public static long CountSubstrings(string s) {
        if (string.IsNullOrEmpty(s)) return 0;
        long count = 0;
        for (int c = 0; c < 2 * s.Length - 1; c++) {      // 2n-1 centres: on a char, or between two
            int l = c / 2, r = l + c % 2;
            while (l >= 0 && r < s.Length && s[l] == s[r]) { count++; l--; r++; }
        }
        return count;
    }

    // The longest palindromic substring; the leftmost one if several share the maximum length.
    public static string Longest(string s) {
        if (string.IsNullOrEmpty(s)) return "";
        int bestL = 0, bestLen = 1;
        for (int c = 0; c < 2 * s.Length - 1; c++) {
            int l = c / 2, r = l + c % 2;
            while (l >= 0 && r < s.Length && s[l] == s[r]) { l--; r++; }
            int len = r - l - 1;
            if (len > bestLen) { bestLen = len; bestL = l + 1; }
        }
        return s.Substring(bestL, bestLen);
    }
}
